float gaussian(float x, float b) {
  return 1./pow(2., (pow(x-b, 2.)));
}

float interact(float x, float y, float z) {
  float f = 0.03;
  return x + y * f - z * f/100.;
}

vec3 activation(float r, float g, float b) {
  float i_r = interact(r, g, b);
  float i_g = interact(g, b, r);
  float i_b = interact(b, r, g);
  float g_b = 3.52;
  r = gaussian(i_r, g_b);
  g = gaussian(i_g, g_b);
  b = gaussian(i_b, g_b);
  return vec3(r, g, b);
}
